    <div><label for="tipo-item-{{ $index }}" class="mb-1.5 block text-sm font-semibold">Tipo do item *</label><select id="tipo-item-{{ $index }}" name="itens[{{ $index }}][tipo_item]" data-fin-field="tipo_item" class="field" required>@foreach(\App\Modules\Financeiro\Models\ItemTransacao::TIPOS as $value => $label)<option value="{{ $value }}" @selected($get('tipo_item', 'ALIMENTO') === $value)>{{ $label }}</option>@endforeach</select></div>
