        <div data-fin-reference="{{ $kind }}"><label for="{{ $field }}-{{ $index }}" class="mb-1.5 block text-sm font-semibold">{{ $label }} *</label><select id="{{ $field }}-{{ $index }}" name="itens[{{ $index }}][{{ $field }}]" data-fin-field="{{ $field }}" class="field"><option value="">Selecione</option>@foreach($records as $record)<option value="{{ $record->id }}" @selected($get($field) === (string) $record->id)>{{ $kind === 'ANIMAL' ? $record->brinco.' · '.$record->nome_ou_numero : $record->nome.' ('.$record->unidade.')' }}</option>@endforeach</select></div>
