    <div data-fin-free><label for="unidade-{{ $index }}" class="mb-1.5 block text-sm font-semibold">Unidade *</label><select id="unidade-{{ $index }}" name="itens[{{ $index }}][unidade]" data-fin-field="unidade" class="field">@foreach(\App\Modules\Financeiro\Models\Produto::UNIDADES as $unit)<option value="{{ $unit }}" @selected($get('unidade', 'UN') === $unit)>{{ $unit }}</option>@endforeach</select></div>
    <div><label for="descricao-{{ $index }}" class="mb-1.5 block text-sm font-semibold">Descrição do item</label><input id="descricao-{{ $index }}" name="itens[{{ $index }}][descricao]" data-fin-field="descricao" value="{{ $get('descricao') }}" class="field" maxlength="255" placeholder="Opcional para itens cadastrados"></div>
    <div><label for="quantidade-{{ $index }}" class="mb-1.5 block text-sm font-semibold">Quantidade *</label><input id="quantidade-{{ $index }}" name="itens[{{ $index }}][quantidade]" data-fin-field="quantidade" value="{{ $get('quantidade', '1') }}" class="field" type="number" required min="0.001" max="999999999.999" step="0.001" inputmode="decimal"></div>
    <div><label for="valor_unitario-{{ $index }}" class="mb-1.5 block text-sm font-semibold">Preço unitário (R$) *</label><input id="valor_unitario-{{ $index }}" name="itens[{{ $index }}][valor_unitario]" data-fin-field="valor_unitario" value="{{ $get('valor_unitario') }}" class="field" type="number" required min="0.01" max="999999999999.99" step="0.01" inputmode="decimal"></div>
